  margin: 0 !important;
}

.forminator-ui.forminator-custom-form[data-design="flat"]:not(
    .forminator-size--small
  ) {
  margin: 0 !important;
}

.forminator-ui.forminator-custom-form[data-design="flat"] {
  margin: 0 !important;
}

/* Form Wrapper */
.forminator-custom-form {
  font-family: var(--global-font-family);
  font-size: var(--text-lg-global);
  font-weight: var(--global-font-weight);
  background-color: #ffffff;
  padding: 2rem;
  border-radius: 1.5rem;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.05);
  max-width: 600px;
  margin: auto;
}

.forminator-row {
  margin-bottom: 0 !important;
}

/* Form Fields */
.forminator-field {
  margin-bottom: unset;
}
/* .forminator-col .forminator-field {
  margin-bottom: 0;
} */

/* Field Labels */
.forminator-label {
  font-family: var(--e-global-typography-9c0bb5a-font-family), Sans-serif;
  font-size: var(--text-lg-global);
  font-weight: var(--global-font-weight);
  color: #101820;
  margin-bottom: 0.5rem;
  display: none;
}

/* Input, Textarea, Select */
.forminator-input,
.forminator-textarea,
.forminator-select {
  width: 100%;
  font-size: var(--text-lg-global);
  padding: 0.75rem 1rem;
  border: 1px solid #e0e0e0;
  border-radius: 8px;
  background-color: #fafafa;
  transition: border-color 0.3s, box-shadow 0.3s;
}

.forminator-input:focus,
.forminator-textarea:focus,
.forminator-select:focus {
  border-color: #ece4d7;
  /* box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.1); */
  outline: none;
}

/* Submit Button */
.forminator-button-submit {
  font-size: var(--text-lg-global);
  font-weight: var(--global-font-weight);
  background-color: #257a88;
  color: #fff;
  border: none;
  padding: 0.75rem 2.5rem;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.3s, transform 0.2s;
  margin-top: 20px !important;
  margin-bottom: 0 !important;
}

.forminator-button-submit:hover {
  background-color: #07272d;
  color: #fff;
  /* transform: translateY(-2px); */
  box-shadow: none !important;
}

/* Checkboxes and Radio */
.forminator-checkbox,
.forminator-radio {
  margin-bottom: 1rem;
}

.forminator-checkbox input:checked + span,
.forminator-radio input:checked + span {
  font-weight: 600;
  color: #4f46e5;
}

.forminator-ui.forminator-custom-form[data-design="flat"]
  .forminator-error-message {
  border-radius: var(--global-border-radius);
}

/* Error Messages */
.forminator-error-message {
  color: #e11d48;
  font-size: 0.875rem;
  margin-top: 0.25rem;
}

/* Success Message */
.forminator-response-message.forminator-success {
  background-color: #d1fae5;
  color: #065f46;
  padding: 1rem;
  border-radius: 0.75rem;
  margin-top: 1.5rem;
  font-weight: 500;
}";s:13:"sc_email_link";s:1:"1";s:10:"sc_message";s:417:"<p>Your form has been saved as draft and a resume link has been generated so you can return to the form anytime within {retention_period} days from today. Copy and save the link or enter your email address below to have the link sent to your mail.</p><p>These fields weren't saved to your submission draft: Paypal, Stripe, Signature, Password, Captcha, and Upload. Kindly fill them out before submitting the form.</p>";s:18:"notification_count";i:2;s:15:"previous_status";s:7:"publish";}s:9:"client_id";N;s:22:"integration_conditions";a:0:{}s:9:"behaviors";a:1:{i:0;a:10:{s:4:"slug";s:18:"behavior-1234-4567";s:5:"label";s:0:"";s:14:"autoclose-time";s:1:"5";s:9:"autoclose";s:4:"true";s:6:"newtab";s:7:"sametab";s:16:"thankyou-message";s:57:"Thank you for contacting us, we will be in touch shortly.";s:22:"email-thankyou-message";s:0:"";s:23:"manual-thankyou-message";s:0:"";s:20:"submission-behaviour";s:18:"behaviour-thankyou";s:12:"redirect-url";s:0:"";}}s:13:"notifications";a:2:{i:0;a:8:{s:4:"slug";s:22:"notification-1234-4567";s:5:"label";s:11:"Admin Email";s:16:"email-recipients";s:7:"default";s:10:"recipients";s:38:"jon@pepco.com.au, info@humansoferp.com";s:13:"email-subject";s:61:"Subscribe from HoE website - #{submission_id} for {form_name}";s:12:"email-editor";s:114:"You have a new website form submission: <br /> {all_fields} <br />---<br /> This message was sent from {site_url}.";s:16:"email-attachment";s:4:"true";s:4:"type";s:7:"default";}i:1;a:6:{s:4:"slug";s:22:"notification-4421-1496";s:5:"label";s:16:"Development Test";s:13:"email-subject";s:16:"Development Test";s:12:"email-editor";s:113:"<p>You have a new website form submission: <br>{all_fields} <br>---<br>This message was sent from {site_url}.</p>";s:10:"recipients";s:54:"madebysev7n@gmail.com, airen.petalbert@maintain.com.au";s:10:"conditions";a:0:{}}}}

