((w) => {
 let $;
 w.addEventListener("load", () => {
 $ = jQuery;
 const allSliders = $(".main_slider .slick-slider");
 if (allSliders.length === 0) {
 console.log("No slider element found");
 return;
 }

 allSliders.each(function () {
 const slider = $(this);
 if (slider.hasClass("slick-initialized")) {
 slider.slick('unslick');
 }

 const targetSpeed = 10000;

 const slickSettings = {
 dots: false,
 infinite: true,
 slidesToShow: 5,
 autoplay: true,
 autoplaySpeed: 0,
 speed: targetSpeed,
 cssEase: "linear",
 centerMode: true,
 accessibility: false,
