 variableWidth: false, // Disable marquee-style
 speed: 600, // Normal transition speed
 autoplaySpeed: 3000, // Slide every 3 sec
 cssEase: "ease", // Smoother snap transition
 draggable: true,
 swipe: true,
 touchMove: true,
 centerMode: false,
 arrows: false
 }
 }
 ]
 };

 slider.slick(slickSettings);
 slider.slick("setPosition");
